Proceso Promedio
    Definir Mutable primera Como Entero <- 0;
    Definir Mutable segunda Como Entero <- 0;
    Definir Mutable tercera Como Entero <- 0;
    Leer primera;
    Leer segunda;
    Leer tercera;
    Definir promedio Como Real <- (primera + segunda + tercera) / 3;
    Escribir promedio;
FinProceso
